select
ingredients.*
from ingredients ingredients

    and ingredients.id = #{id}
    and ingredients.name like concat('%',#{name},'%')
    and ingredients.img = #{img}
    and ingredients.info = #{info}
    and ingredients.type = #{type}
    and ingredients.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from ingredients ingredients

    and ingredients.id = #{id}
    and ingredients.name like concat('%',#{name},'%')
    and ingredients.img = #{img}
    and ingredients.info = #{info}
    and ingredients.type = #{type}
    and ingredients.create_time = #{createTime}
